select distinct ur.user_id
  from rm_user_role_rela_t ur
  join rm_role_t r on r.id = ur.role_id
 where r.app_id = #{appId}
   and r.code_num = #{roleCode}
   and ur.tenant_id = #{tenantId}
   and r.tenant_id = #{tenantId}
   and r.deleted = 0
   and r.status = 0

